// 1. Captura os dados brutos do pedido (do nó do print)
// ⚠️ ATENÇÃO: Substitua 'NOME_DO_NO_EDIT_FIELDS' pelo nome exato do nó da imagem!
let dadosPedido = $('Edit Fields').first().json || {};

// 2. Captura a saída do NÓ DA CALCULADORA (O nó de código que gerou os R$)
// ⚠️ ATENÇÃO: Verifique se 'Code_Calculadora' é o nome exato do nó!
let dadosCalculo = $('Code_Calculadora').first().json || {};

// 3. Captura a saída do AGENTE 2 (Stella - Mensagem)
let mensagemStella = $input.first().json.output || $input.first().json.text || "";

// 4. Limpeza da Mensagem da Stella
if (mensagemStella.includes("SILÊNCIO")) {
  mensagemStella = "";
}
mensagemStella = mensagemStella.replace(/```/g, '').trim();

// 5. Função para remover o "R$" e deixar apenas número para o seu Dashboard
function formatarMoeda(valor) {
  if (valor === undefined || valor === null || valor === "") return "0,00";
  let textoValor = String(valor).replace(/[^\d.,]/g, '');
  if (textoValor.includes(',') && textoValor.includes('.')) {
    textoValor = textoValor.replace(/\./g, '').replace(',', '.');
  } 
  else if (textoValor.includes('.') && textoValor.split('.').pop().length <= 3) {
    // Mantém ponto como decimal
  } 
  else { 
    textoValor = textoValor.replace(',', '.'); 
  }

  let numeroLimpo = Number(textoValor);
  return isNaN(numeroLimpo) ? "0,00" : numeroLimpo.toFixed(2).replace('.', ',');
}

// 6. Mapeamento - DADOS DO PEDIDO (Vindos do nó Edit Fields)
const whatsFinal = (String(dadosPedido?.Whats).toLowerCase() === 'true') ? true : null;
const responsavelNome = dadosPedido?.Responsavel || "Atendente";
const clienteNome = dadosPedido?.Cliente || "Cliente";
const largura = dadosPedido?.Larg || "";
const altura = dadosPedido?.Alt || "";
const tecidoOriginal = dadosPedido?.Tecido || "";
const quantidade = dadosPedido?.Qtd || 1;
const corFerragem = dadosPedido?.["Cor Ferragem"] || "";
const acabamentos = dadosPedido?.Acabamentos || "";
const modeloPersiana = dadosPedido?.["Modelo de Persiana"] || "";

// 7. Mapeamento - DADOS DO CÁLCULO E IA (Vindos da Calculadora)
const nomenclaturaComercial = dadosCalculo?.nomenclatura_comercial || tecidoOriginal;
const resumoCalculo = dadosCalculo?.resumo_agente_calculo || dadosCalculo?.resumo_execucao || "";
const erroCalculo = dadosCalculo?.erro || false;

// Custos (Novo Caminho da IA)
const custoOrcamento = dadosCalculo?.custos?.rolo_total || dadosCalculo?.custos?.resumo_custos?.custo_rolo_total || 0;
const custoM2 = dadosCalculo?.custos?.custo_por_m2 || dadosCalculo?.custos?.resumo_custos?.custo_por_m2 || 0;
const custoAcabamento = dadosCalculo?.custos?.acabamento_total || dadosCalculo?.custos?.resumo_custos?.custo_acabamento_total || 0;

// Valores de Venda (Se existirem)
const valorVenda = dadosCalculo?.vendas?.rolo_4x || 0;
const valorInstalacao = dadosCalculo?.vendas?.instalacao || dadosCalculo?.custos?.resumo_custos?.instalacao_total || 0;
const valorAcabVenda = dadosCalculo?.vendas?.acabamento_4x || 0;

// 8. Saída Consolidada para atualizar Planilha e Dashboard/Supabase
return [{
  json: {
    // Infos Originais
    whats: whatsFinal,
    nome_do_responsavel: responsavelNome,
    nome_do_cliente: clienteNome,
    modelo_persiana: modeloPersiana,
    tecido_original: tecidoOriginal,
    largura: largura,
    altura: altura,
    quantidade: quantidade,
    cor_ferragem: corFerragem,
    acabamentos: acabamentos,

    // Infos de IA e Cálculo
    custo: formatarMoeda(custoOrcamento),
    custo_m2: formatarMoeda(custoM2),
    custo_acabamento: formatarMoeda(custoAcabamento),
    valor_venda: formatarMoeda(valorVenda),
    valor_venda_acabamento: formatarMoeda(valorAcabVenda),
    valor_instalacao: formatarMoeda(valorInstalacao),
    nomenclatura_comercial: nomenclaturaComercial,
    resumo_calculo: resumoCalculo,
    erro: erroCalculo,

    // Mensagem WhatsApp
    resumo_curto_valor_ao_cliente: mensagemStella,

    // Identificação do ambiente (para combinação de mensagens no Supervisor)
    ambiente: dadosPedido?.ambiente || '',
    ambiente_label: dadosPedido?.ambiente_label || dadosPedido?.ambiente || '',
    ambiente_index: parseInt(dadosPedido?.ambiente_index) || 0,
    total_ambientes: parseInt(dadosPedido?.total_ambientes) || 1,
    preco_instalacao_total: dadosPedido?.preco_instalacao_total ?? null,
    instalacao_sob_consulta: dadosPedido?.instalacao_sob_consulta ?? false,
    persiana_grupo: dadosPedido?.persiana_grupo || null,
  }
}];

