// 1. Pega os dados do Agente 1 (Investigador de Custos)
let inputData = $input.first().json.output || $input.first().json.text || "{}";
let jsonData = {};

// FALLBACK: detecta alucinacao 'Calling Calculator with input: {...}'
// Se o agente retornou esse padrao em vez do JSON final, avalia a expressao
// e retorna erro descritivo para rastreio.
const callingMatch = inputData.match(/Calling Calculator with input:\s*\{[^}]*?"input"\s*:\s*"([^"]+)"/);
if (callingMatch && !inputData.includes('"custos"') && !inputData.includes('"responsavel"')) {
  try {
    const expr = callingMatch[1].replace(/[^0-9+\-*/.() ]/g, '');
    const resultado = Function('return ' + expr)();
    if (isFinite(resultado) && resultado > 0) {
      return [{ json: {
        erro: true,
        mensagem: "Agente interrompido antes do JSON final (alucinacao Calculator). Valor parcial: " + resultado.toFixed(2) + ". Reprocesse o item.",
        valor_parcial: resultado,
        expressao_capturada: callingMatch[1]
      }}];
    }
  } catch(e) {}
}

try {
  // Tenta todos os blocos JSON do texto e usa o que tiver a estrutura de custos
  const allMatches = [...inputData.matchAll(/\{[\s\S]*?\}/g)].map(m => m[0]);
  // Regex greedy para pegar JSON maior tambem
  const greedyMatch = inputData.match(/\{[\s\S]*\}/);
  const candidates = greedyMatch ? [greedyMatch[0], ...allMatches] : allMatches;

  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      // JSON valido de custos precisa ter 'custos' ou 'responsavel' - nao e um call de tool
      if (parsed.custos || parsed.responsavel || parsed.erro === true) {
        jsonData = parsed;
        break;
      }
    } catch (e) {}
  }

  // Se nenhum candidato valido, tenta parse direto
  if (!jsonData.custos && !jsonData.responsavel && !jsonData.erro) {
    const jsonMatch = inputData.match(/\{[\s\S]*\}/);
    jsonData = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(inputData);
  }
} catch (e) {
  return [{ json: { erro: true, mensagem: "Falha ao ler JSON do Agente." } }];
}

// Guarda de seguranca: se o JSON nao tem estrutura de custos (ex: e um call de Calculator),
// retorna erro para evitar que valores zerados poluam o orcamento.
if (!jsonData.custos && !jsonData.responsavel && jsonData.erro !== true) {
  return [{ json: { erro: true, mensagem: "Output do agente nao contem JSON de custos. Possivel resposta intermediaria capturada." } }];
}

if (jsonData.erro) {
  return [{ json: jsonData }];
}

// 2. Extrai as Variaveis de Custo e Resumo
const qtd = Number(jsonData.quantidade) || 1;
const custoRoloTotal = Number(jsonData.custos?.resumo_custos?.custo_rolo_total) || 0;
const custoAcabamentoTotal = Number(jsonData.custos?.resumo_custos?.custo_acabamento_total) || 0;
const custoM2 = Number(jsonData.custos?.resumo_custos?.custo_por_m2) || 0;
const instalacaoTotal = Number(jsonData.custos?.resumo_custos?.instalacao_total) || 0;
const resumoExecucao = jsonData.resumo_execucao || "Sem resumo gerado.";

// Determina se vai pro WhatsApp
const whatsBool = (String(jsonData.whats).toLowerCase() === 'true');

// 3. Matematica de VENDA (Somente se whats == true)
let vendaRolo4x = 0;
let vendaAcabamento4x = 0;

function arredondarVenda(valor) {
  return Math.ceil(valor * 10) / 10;
}

// Kit_Box: custo incluido no valor da Rolo (mesmo markup 2.8x)
const acabamentoType = ($('Edit Fields').first().json.Acabamentos || '').toLowerCase().trim();
const isKitBox = acabamentoType === 'kit_box' || acabamentoType === 'kit box';

if (whatsBool) {
  if (isKitBox) {
    vendaRolo4x = arredondarVenda((custoRoloTotal + custoAcabamentoTotal) * 2.8 * 1.06 * 1.06);
    vendaAcabamento4x = 0;
  } else {
    vendaRolo4x = arredondarVenda(custoRoloTotal * 2.8 * 1.06 * 1.06);
    vendaAcabamento4x = arredondarVenda(custoAcabamentoTotal * 2.2 * 1.06 * 1.06);
  }
}

// 4. Formatacao de Moeda Brasileira 'R$ 0.000,00'
function formatarBRL(valor) {
  if (isNaN(valor)) return 'R$ 0,00';
  return 'R$ ' + valor.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// 5. Montagem do Objeto Final
return [{
  json: {
    responsavel: jsonData.responsavel,
    linha: jsonData.linha,
    cliente: jsonData.cliente,
    whats: whatsBool,
    erro: false,
    nomenclatura_comercial: jsonData.nomenclatura_comercial,
    quantidade: qtd,
    resumo_agente_calculo: resumoExecucao,

    // Custos Formatados
    custos: {
      rolo_total: formatarBRL(custoRoloTotal),
      acabamento_total: formatarBRL(custoAcabamentoTotal),
      custo_por_m2: formatarBRL(custoM2),
      instalacao: formatarBRL(instalacaoTotal)
    },

    // Valores de Venda Formatados
    kit_box_incluso_na_rolo: isKitBox && custoAcabamentoTotal > 0,
    vendas: {
      rolo_4x: formatarBRL(vendaRolo4x),
      acabamento_4x: formatarBRL(vendaAcabamento4x),
      instalacao: formatarBRL(instalacaoTotal)
    }
  }
}];

// Branch SEM WhatsApp: retorna custos ao Supervisor para salvar no Supabase

// 1. Dados do pedido
const pedido = $('Edit Fields').first().json;

// 2. Output do Agent1 — parse do JSON de custos
let rawOutput = $input.first().json.output || $input.first().json.text || '{}';
rawOutput = rawOutput.replace(/```json/g, '').replace(/```/g, '').trim();
let jsonData = {};
try {
  const match = rawOutput.match(/\{[\s\S]*\}/);
  jsonData = match ? JSON.parse(match[0]) : {};
} catch(e) {}

const resumo = jsonData.custos?.resumo_custos || {};

// 3. Campo de custo principal varia por modelo (custo_rolo_total, custo_double_total, etc.)
const mainKey = Object.keys(resumo).find(k =>
  k.includes('_total') && !k.includes('acabamento') && !k.includes('instalacao')
);
const custoBase      = mainKey ? Number(resumo[mainKey]) || 0 : 0;
const custoM2        = Number(resumo.custo_por_m2)            || 0;
const custoAcab      = Number(resumo.custo_acabamento_total)   || 0;
const instalacao     = Number(resumo.instalacao_total)         || 0;

function fmt(v) {
  return Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

const corFerragem = pedido['Cor Ferragem'] || pedido['Cor Ferragem /Motor'] || '';

return [{
  json: {
    nome_do_responsavel:           pedido.Responsavel             || null,
    nome_do_cliente:               pedido.Cliente                  || null,
    largura:                       String(pedido.Larg || ''),
    altura:                        String(pedido.Alt  || ''),
    modelo_persiana:               pedido['Modelo de Persiana']    || null,
    tecido_original:               pedido.Tecido                   || null,
    quantidade:                    pedido.Qtd                      || 1,
