    acabamentos:                   pedido.Acabamentos              || '',
    ambiente:                      pedido.ambiente                 || null,
    ambiente_label:                pedido.ambiente_label           || pedido.ambiente || null,
    custo:                         fmt(custoBase),
    custo_m2:                      fmt(custoM2),
    custo_acabamento:              fmt(custoAcab),
    valor_instalacao:              fmt(instalacao),
    valor_venda:                   null,
    whats:                         false,
    resumo_curto_valor_ao_cliente: '',
    total_ambientes:               pedido.total_ambientes          || 1,
    ambiente_index:                pedido.ambiente_index           || 0,
    _tipo:                         'custo_interno',
    preco_instalacao_total: pedido.preco_instalacao_total ?? null,
    instalacao_sob_consulta: pedido.instalacao_sob_consulta ?? false,
    persiana_grupo: pedido.persiana_grupo || null,
  }
}];

// Prepara dados de custo interno para salvar no Supabase (custos_internos).
// Converte strings BRL → números e mapeia campos.
const item = $input.first().json;

function parseBR(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number') return value;
  const r = parseFloat(String(value).replace(/\./g, '').replace(',', '.'));
  return isNaN(r) ? null : r;
}

return [{
  json: {
    responsavel:        item.nome_do_responsavel  || null,
    cliente:            item.nome_do_cliente       || null,
    modelo:             item.modelo_persiana       || null,
    tecido:             item.tecido_original       || null,
    largura:            parseFloat(item.largura)   || null,
    altura:             parseFloat(item.altura)    || null,
    quantidade:         parseInt(item.quantidade)  || 1,
    cor_ferragem_motor: item.cor_ferragem          || null,
    acabamentos:        item.acabamentos           || null,
    custo_material:     parseBR(item.custo),
    custo_m2:           parseBR(item.custo_m2),
    custo_acabamento:   parseBR(item.custo_acabamento),
    custo_instalacao:   item.preco_instalacao_total != null
                          ? item.preco_instalacao_total
                          : parseBR(item.valor_instalacao),
    ambiente:           item.ambiente              || null,
    fonte:              'supervisor-custo-interno',
    // Marcador para o Supervisor ignorar este item em orcamentos
    _tipo:              'custo_interno',
  }
}];

// Code_Validar_Output
// Valida se o agente retornou um JSON de custos válido
// Output 0: válido → segue fluxo normal
// Output 1: inválido → precisa retry

const rawOutput = $input.first().json.output || $input.first().json.text || '';
let jsonData = {};

try {
  const greedyMatch = rawOutput.match(/\{[\s\S]*\}/);
  if (greedyMatch) {
    jsonData = JSON.parse(greedyMatch[0]);
  }
} catch(e) {
  jsonData = {};
}

// Detecta tool call alucinado
const toolCallKeys = ['tool', 'tool_call', 'function_call', 'name', 'arguments'];
const isToolCall = toolCallKeys.some(k => jsonData[k] !== undefined && !jsonData.responsavel);

// Verifica estrutura mínima esperada
const temResponsavel = !!(jsonData.responsavel && typeof jsonData.responsavel === 'string' && jsonData.responsavel.length > 0);
const temCustos = !!(jsonData.custos && typeof jsonData.custos === 'object' && Object.keys(jsonData.custos).length > 0);
const temCampoAlternativo = !!(jsonData.custo_material || jsonData.preco_final || jsonData.valor_venda);

const isValido = (temResponsavel && (temCustos || temCampoAlternativo)) && !isToolCall;

if (isValido) {
  return [[{ json: $input.first().json }], []];
} else {
  const itemOriginal = $input.first().json;
  return [[], [{
    json: {
      ...itemOriginal,
      _output_invalido: rawOutput.slice(0, 300),
      _retry_count: (itemOriginal._retry_count || 0) + 1
    }
  }]];
}

